mid.H5:
WITH agg AS (
  SELECT {CATEGORY_TOPIC} AS topic, {NAME_ENTITY} AS entity_name, SUM({VAL_QUANTITY}) AS qty
  FROM {EVENT_SCOPE[CATEGORY_TOPIC, NAME_ENTITY, VAL_QUANTITY]}
  GROUP BY {CATEGORY_TOPIC}, {NAME_ENTITY}
),
ranked AS (
  SELECT *,
 ROW_NUMBER() OVER (PARTITION BY topic ORDER BY qty DESC) AS rn
  FROM agg
)
SELECT topic, entity_name, qty
FROM ranked
WHERE rn = 1
ORDER BY qty DESC
LIMIT :k;

