mid.M6:
WITH per_day AS (
SELECT {LEVEL} AS lvl, DATE({TIME_EVENT}) AS d, COUNT(*) AS cnt
FROM {EVENT_SCOPE[TIME_EVENT, LEVEL]}
WHERE {TIME_EVENT} >= :start_time AND {TIME_EVENT} < :end_time
GROUP BY {LEVEL}, DATE({TIME_EVENT})
)
SELECT lvl, d, cnt,
   SUM(cnt) OVER (PARTITION BY lvl ORDER BY d ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_cnt
FROM per_day
ORDER BY lvl, d;

mid.M7:
WITH cell AS (
SELECT {CATEGORY_TOPIC} AS topic, {LEVEL} AS lvl, COUNT(*) AS cnt
FROM {EVENT_SCOPE[CATEGORY_TOPIC, LEVEL]}
GROUP BY {CATEGORY_TOPIC}, {LEVEL}
),
topic_total AS (
SELECT topic, SUM(cnt) AS total FROM cell GROUP BY topic
),
ranked AS (
SELECT c.topic, c.lvl, c.cnt, t.total,
   CAST(c.cnt AS DOUBLE) / NULLIF(t.total, 0) AS share,
   ROW_NUMBER() OVER (PARTITION BY c.topic ORDER BY c.cnt DESC) AS rn
FROM cell c JOIN topic_total t ON c.topic = t.topic
)
SELECT topic, lvl, cnt, share FROM ranked
WHERE rn = 1 AND share >= :min_share
ORDER BY share DESC;

mid.M8:
WITH win_a AS (
SELECT DISTINCT {REL_PERSON} AS person
FROM {EVENT_SCOPE[ID_MAIN, REL_PERSON, TIME_EVENT]}
WHERE {TIME_EVENT} >= :start_a AND {TIME_EVENT} < :end_a
),
win_b AS (
SELECT DISTINCT {REL_PERSON} AS person
FROM {EVENT_SCOPE[ID_MAIN, REL_PERSON, TIME_EVENT]}
WHERE {TIME_EVENT} >= :start_b AND {TIME_EVENT} < :end_b
)
SELECT a.person FROM win_a a
WHERE NOT EXISTS (SELECT 1 FROM win_b b WHERE b.person = a.person)
ORDER BY a.person LIMIT :k;

